import React, { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { fetchJobs } from "../Features/JobSlice";
import { applyJob } from "../Features/ApplicationSlice";
import "../Styles/FindJob.css";

const FindJob = () => {
  const dispatch = useDispatch();
  // Logout function to clear user session and navigate to login
  const handleLogout = async () => {
    // Remove all saved session data
    localStorage.removeItem("role");
    localStorage.removeItem("loggedUser");
    localStorage.removeItem("token"); // optional if you used token
    localStorage.removeItem("applications");

    // Also reset Redux state
    dispatch(logout());

    // Small delay before navigation
    await new Promise((resolve) => setTimeout(resolve, 100));
    navigate("/login");
  };

  const { jobs, isLoading } = useSelector((state) => state.jobs);
  const { isSuccess } = useSelector((state) => state.applications);
  const [searchTerm, setSearchTerm] = useState("");

  // Load jobs from MongoDB
  useEffect(() => {
    dispatch(fetchJobs());
  }, [dispatch]);

  // Filter jobs based on search input
  const filteredJobs = jobs.filter(
    (job) =>
      job.jobTitle.toLowerCase().includes(searchTerm.toLowerCase()) ||
      job.organization.toLowerCase().includes(searchTerm.toLowerCase()) ||
      job.skills.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Apply for a job
  const handleApply = (job) => {
    const loggedUser = JSON.parse(localStorage.getItem("loggedUser"));
    if (!loggedUser) {
      alert("Please login first.");
      return;
    }

    const applicationData = {
      jobId: job._id,
      jobTitle: job.jobTitle,
      organization: job.organization,
      applicantEmail: loggedUser.email,
      applicantName: loggedUser.name,
    };

    dispatch(applyJob(applicationData))
      .unwrap()
      .then(() => alert("Job applied successfully."))
      .catch(() => alert("You already applied or an error occurred."));
  };

  if (isLoading) return <p>Loading jobs...</p>;

  return (
    <div className="findjob-page">
      <h1 className="findjob-title">
        Find <span className="accent">Job</span>
      </h1>

      {/* Search bar */}
      <div className="search-container">
        <div className="search-wrapper">
          <input
            type="text"
            placeholder="Search skills, companies"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="search-box"
          />
        </div>
        <button className="search-btn">Search</button>
      </div>

      {/* Job listings */}
      <div className="job-list">
        {filteredJobs.length === 0 ? (
          <p className="no-jobs">No jobs found.</p>
        ) : (
          filteredJobs.map((job, index) => (
            <div key={index} className="job-card">
              <div className="job-header">
                <h3>{job.jobTitle}</h3>
                <span className="rate">
                  {job.rate} OMR · {job.rateType}
                </span>
              </div>

              <p className="org-name">{job.organization}</p>

              <div className="tags">
                <span className="tag">{job.sector}</span>
                <span className="tag">{job.category}</span>
                {job.payout && <span className="tag">{job.payout}</span>}
              </div>

              <p className="desc">{job.description}</p>
              <p className="skills">Skills: {job.skills}</p>

              <div className="job-actions">
                <button className="btn-apply" onClick={() => handleApply(job)}>
                  Apply ➜
                </button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default FindJob;
